function NAT_BOX(S, N):
    return { m in 0..N-1 : for all j < m, j in S }

function ITERATE_BOX(N, K):
    cur <- emptyset            # ⊥
    chain <- [cur]
    for step in 1..K:
        cur <- NAT_BOX(cur, N)
        chain.append(cur)
    return chain               # chain[k] = □^k(∅) = {0,...,k-1}

function GRADED_GODEL_II(N):
    chain <- ITERATE_BOX(N, N)
    for k in 0..N-2:
        stmt <- chain[k+1]                 # □^{k+1}⊥
        con  <- IMPLIES(stmt, emptyset, N) # consistency statement
        assert NAT_BOX(con, N) != universe(N)   # unprovable

